sources.shared-decision.json:
{
  "specVersion": "0.2.0-draft.2",
  "kind": "scenario",
  "id": "scenario:shared-decision",
  "resources": {
    "character:aya": {
      "path": "characters/aya.simkind.json"
    },
    "character:mira": {
      "path": "characters/mira.simkind.json"
    },
    "character:sol": {
      "path": "characters/sol.simkind.json"
    },
    "catalog:conversation": {
      "path": "tools/conversation.json"
    }
  },
  "host": {
    "contractId": "example.conversation",
    "version": "1.0.0"
  },
  "cast": [
    {
      "instanceId": "simkin:aya",
      "characterRef": "character:aya"
    },
    {
      "instanceId": "simkin:mira",
      "characterRef": "character:mira"
    },
    {
      "instanceId": "simkin:sol",
      "characterRef": "character:sol"
    }
  ],
  "toolCatalogRef": "catalog:conversation",
  "initialConditions": {
    "sharedContext": "A small group must choose how to use a grant. Discuss tradeoffs and record a vote when you wish. You may revise your vote or decline to vote.",
    "options": [
      "workshop",
      "garden",
      "save"
    ]
  },
  "recommendations": {
    "features": {
      "simkind.memory-retrieval": {
        "config": {
          "maxItems": 6
        }
      }
    }
  }
}

sources.tools/conversation.json:
{
  "specVersion": "0.2.0-draft.2",
  "kind": "tool-catalog",
  "id": "catalog:conversation",
  "host": {
    "contractId": "example.conversation",
    "version": "1.0.0"
  },
  "tools": [
    {
      "id": "say",
      "version": "1.0.0",
      "description": "Say something to the group or privately to one participant. Speech does not cast a vote.",
      "inputSchema": {
        "type": "object",
        "additionalProperties": false,
        "required": [
          "text",
          "to"
        ],
        "properties": {
          "text": {
            "type": "string",
            "maxLength": 4000
          },
          "to": {
            "type": [
              "string",
              "null"
            ]
          }
        }
      },
      "lifecycle": {
        "asynchronous": false,
        "cancellable": false
      }
    },
    {
      "id": "vote",
      "version": "1.0.0",
      "description": "Record or revise your vote for one of the offered options. No agreement is required.",
      "inputSchema": {
        "type": "object",
        "additionalProperties": false,
        "required": [
          "option"
        ],
        "properties": {
          "option": {
            "type": "string"
          }
        }
      },
      "lifecycle": {
        "asynchronous": false,
        "cancellable": false
      }
    }
  ]
}
